terminal=set()
with gzip.open(JOB,'rt') as f:
  for line in f:
    p=line.rstrip('\n').split(',')
    if len(p)<4: continue
    if int(p[3]) in (3,4,5,6):
      terminal.add(int(p[2]))
ref={}
